/**
 * MegaMUD 2.1's character settings dialog, as data: its sixteen tabs in
 * the order `0x49eea0` adds them, each tab's controls where `MegaRes.dll`'s
 * dialog template puts them (dialog units), and the setting each control
 * shows, as the tab's own procedure reads and writes it (read 2026-10-13).
 *
 * Generated by `~/tools/port/settings_tabs.py`; do not edit. A control with
 * no `bind` is one the dialog fills from elsewhere (a list of paths, the
 * sound files, the toolbar) and is drawn but not yet editable here.
 */
import type { ProfiledSection } from './settings';

export type ControlKind =
  'label' | 'group' | 'edit' | 'combo' | 'check' | 'radio' | 'button' | 'list' | 'other';

/** How a control shows its setting. */
export interface ControlBind {
  section: string;
  key: string;
  /** `int`/`text` an edit or combo's text, `check` on or off, `radio` on when the value is `value`, `bit` on when `bit` is set, `index` a combo's choice. */
  as: 'int' | 'text' | 'check' | 'radio' | 'bit' | 'index';
  value?: number;
  bit?: number;
}

/** A row of a list of switches (`0x4201e0`): a heading, or a switch or one of a choice with its own setting. */
export interface ChecklistRow {
  label: string;
  kind: 'header' | 'check' | 'radio';
  section?: string;
  key?: string;
  /** A choice's value. */
  value?: number;
}

export interface TabControl {
  id: number;
  kind: ControlKind;
  text: string;
  x: number;
  y: number;
  w: number;
  h: number;
  hidden?: true;
  bind?: ControlBind;
  rows?: ChecklistRow[];
  options?: string[];
  /** One of the four profile buttons (1–4), or a profile's Enabled switch (2–4). */
  profile?: number;
  profileEnabled?: number;
}

export interface SettingsTab {
  title: string;
  /** The dialog template in `MegaRes.dll`, and the tab's procedure in `megamud.exe`. */
  template: number;
  proc: number;
  w: number;
  h: number;
  /** Kept per profile (`Health.P1`…): the tab's settings are a profile's. */
  profiled?: ProfiledSection;
  controls: TabControl[];
}

